// Modelo de juguete: probabilidad anual de perder un objeto con n copias en discos independientes.
// SUPUESTOS míos (no de ningún proveedor): tasa anual de falla de un disco p, ventana de reparación en días.
function perdidaAnual(n, p, ventanaDias){
  const q = p * ventanaDias / 365;      // prob. de que un disco falle durante la ventana
  // una copia falla en el año (n formas) y las otras n-1 fallan dentro de la ventana
  return n * p * Math.pow(q, n-1);
}
for (const n of [1,2,3]) {
  const pl = perdidaAnual(n, 0.02, 1);
  console.log(`n=${n} copias: pérdida anual ≈ ${pl.toExponential(2)}  → durabilidad ≈ ${(1-pl).toFixed(12)}`);
}
const objetos = 10_000_000, pl = 1e-11;
console.log('11 nueves con 10 millones de objetos: pérdidas esperadas por año =', objetos*pl, '→ una cada', 1/(objetos*pl), 'años');

// ¿Cuándo conviene Standard-IA? Precios sa-east-1 al 16-11-2026.
const standard = 0.0405, ia = 0.0221, retiro = 0.01; // USD por GB (retiro: por GB leído)
const ahorroMensual = standard - ia;
console.log('Ahorro por GB y por mes al pasar a IA:', ahorroMensual.toFixed(4), 'USD');
console.log('Punto de equilibrio: leer cada GB menos de', (ahorroMensual / retiro).toFixed(2), 'veces por mes');
for (const lecturasPorMes of [0, 0.5, 1, 2, 4]) {
  const costoIA = ia + lecturasPorMes * retiro;
  console.log(`lecturas/mes=${lecturasPorMes}  Standard=${standard.toFixed(4)}  IA=${costoIA.toFixed(4)}  conviene IA: ${costoIA < standard}`);
}

// Precios de lista de USD por GB, leídos el 16-11-2026 (región sa-east-1 de AWS; R2 sin región).
// Escenario INVENTADO: 2 TB de fotos de entregas guardadas y 3 TB por mes que se bajan a internet.
const GB_ALMACENADOS = 2 * 1024, GB_SALIDA = 3 * 1024;

// S3 Standard, sa-east-1: 0,0405 por GB-mes (primeros 50 TB). Salida a internet: 100 GB gratis al mes
// (global) y luego 0,15 por GB hasta 10 TB.
const s3 = {
  almacenamiento: GB_ALMACENADOS * 0.0405,
  salida: Math.max(0, GB_SALIDA - 100) * 0.15,
};
// R2 Standard: 0,015 por GB-mes con 10 GB gratis; salida a internet gratis.
const r2 = {
  almacenamiento: Math.max(0, GB_ALMACENADOS - 10) * 0.015,
  salida: 0,
};
const f = (n) => n.toFixed(2).padStart(8);
for (const [nombre, c] of [['S3 Standard sa-east-1', s3], ['R2 Standard', r2]]) {
  console.log(nombre.padEnd(22), 'guardar', f(c.almacenamiento), '| salida', f(c.salida), '| total', f(c.almacenamiento + c.salida));
}
console.log('Sin contar pedidos (PUT, GET) ni impuestos.');

// Sacar 50 TB de una vez con la tabla escalonada de salida de sa-east-1
function salida(gb) {
  const tramos = [[10240, 0.15], [40960, 0.138], [102400, 0.126], [Infinity, 0.114]];
  let resto = gb, total = 0;
  for (const [tam, precio] of tramos) {
    const x = Math.min(resto, tam);
    total += x * precio;
    resto -= x;
    if (resto <= 0) break;
  }
  return total;
}
console.log('Bajar 50 TB (51.200 GB) de una vez:', salida(51200).toFixed(2), 'USD');
